SELECT p.name || ' — план говорит «есть», а документа набора нет' AS detail FROM project_document_plan p WHERE p.project_id = $1 AND p.claim = 'present' AND p.planned_kind <> '' AND NOT EXISTS (SELECT 1 FROM project_documents d WHERE d.project_id = p.project_id AND d.entity_kind = p.planned_kind AND d.entity_name = p.planned_name) UNION ALL SELECT p.name || ' — план говорит «нет» и не говорит почему: отсутствие без причины неотличимо от забытого' FROM project_document_plan p WHERE p.project_id = $1 AND p.claim = 'absent' AND trim(regexp_replace(p.state_text, '^[^:]*:?', '')) = '' ORDER BY 1
